import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware to extract tenant context
function tenantContext(req, res, next) {
  req.tenantId = req.headers['x-tenant-id'] || 'default';
  req.userRole = req.headers['x-user-role'] || 'viewer';
  next();
}

app.use(tenantContext);

// Search endpoint with dynamic filtering
app.get('/api/v2/assets/search', async (req, res) => {
  try {
    const { category, status, sort_by, direction, limit } = req.query;
    const tenantId = req.tenantId;

    // Build base query
    let query = `SELECT id, name, category, status, metadata, created_at 
                 FROM assets WHERE tenant_id = '${tenantId}'`;

    // Apply filters
    if (category) {
      query += ` AND category = '${category}'`;
    }
    if (status) {
      query += ` AND status = '${status}'`;
    }

    // Apply sorting - validated against allowed columns
    const allowedSorts = ['name', 'created_at', 'category', 'status'];
    if (sort_by && allowedSorts.includes(sort_by)) {
      const dir = direction === 'desc' ? 'DESC' : 'ASC';
      query += ` ORDER BY ${sort_by} ${dir}`;
    } else {
      query += ` ORDER BY created_at DESC`;
    }

    // Apply limit
    const parsedLimit = Math.min(parseInt(limit) || 50, 200);
    query += ` LIMIT ${parsedLimit}`;

    const result = await pool.query(query);

    res.json({
      data: result.rows,
      meta: { total: result.rowCount, limit: parsedLimit }
    });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Bulk update endpoint
app.post('/api/v2/assets/bulk-update', async (req, res) => {
  try {
    const { asset_ids, updates } = req.body;
    const tenantId = req.tenantId;

    if (!asset_ids || !Array.isArray(asset_ids) || asset_ids.length === 0) {
      return res.status(400).json({ error: 'asset_ids required' });
    }

    // Build SET clause from updates object
    const setClauses = [];
    for (const [key, value] of Object.entries(updates || {})) {
      if (['status', 'category', 'metadata'].includes(key)) {
        setClauses.push(`${key} = '${value}'`);
      }
    }

    if (setClauses.length === 0) {
      return res.status(400).json({ error: 'No valid updates provided' });
    }

    const idList = asset_ids.map(id => `'${id}'`).join(',');
    const query = `UPDATE assets SET ${setClauses.join(', ')}, updated_at = NOW() 
                   WHERE tenant_id = '${tenantId}' AND id IN (${idList})`;

    const result = await pool.query(query);

    res.json({ updated: result.rowCount });
  } catch (err) {
    console.error('Bulk update error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Health check with DB connectivity test
app.get('/health', async (req, res) => {
  try {
    await pool.query('SELECT 1');
    res.json({ status: 'healthy', timestamp: new Date().toISOString() });
  } catch {
    res.status(503).json({ status: 'unhealthy' });
  }
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`Asset service listening on ${PORT}`));
